package com.robot.platform.ai.digitalhuman;import com.robot.platform.ai.realtime.protocol.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DigitalHumanRealtimeStartTest {@Test void codecAcceptsOptionalDigitalHumanCapabilities(){RealtimeClientEvent e=new RealtimeProtocolCodec().decodeClientText("{\"type\":\"session.start\",\"agentCode\":\"a\",\"digitalHumanCode\":\"h\",\"clientCapabilities\":{\"viseme\":true,\"audioLevelLipSync\":true},\"audio\":{\"codec\":\"PCM_S16LE\",\"sampleRate\":16000,\"channels\":1}}");var s=(RealtimeClientEvent.SessionStartEvent)e;assertEquals("h",s.digitalHumanCode());assertTrue(s.clientCapabilities().viseme());}}
